apiIntegrations.responseShape:
interface CoinMarket {
  id: string;            // CoinGecko slug, e.g. 'bitcoin'
  symbol: string;        // ticker symbol, e.g. 'btc' (lowercase — uppercase it for display)
  name: string;          // display name, e.g. 'Bitcoin'
  image: string;         // icon URL (from coingecko CDN)
  current_price: number; // in vs_currency
  market_cap: number;
  market_cap_rank: number;
  price_change_24h: number;
  price_change_percentage_24h: number | null;  // null on brand-new coins — treat as 0 and suppress the change badge for that card
  last_updated: string;  // ISO 8601
}
// the endpoint returns Array<CoinMarket>
